class Solution {
    fun maxEqualFreq(nums:IntArray):Int{
        val valueCount=mutableMapOf<Int,Int>();
        val frequencyCount=mutableMapOf<Int,Int>();
        var maximum=0;
        var answer=0;
        for(i in nums.indices){
            val old=valueCount[nums[i]]?:0;
            if(old>0)frequencyCount[old]=(frequencyCount[old]?:0)-1;
            val current=old+1;
            valueCount[nums[i]]=current;
            frequencyCount[current]=(frequencyCount[current]?:0)+1;
            maximum=maxOf(maximum,current);
            val length=i+1;
            if(maximum==1||maximum*(frequencyCount[maximum]?:0)+1==length||(maximum-1)*((frequencyCount[maximum-1]?:0)+1)+1==length)answer=length
        };
        return answer
    }
}

